func testOrcamentoVendasUpdate(t *testing.T) {
	t.Parallel()

	if 0 == len(orcamentoVendaPrimaryKeyColumns) {
		t.Skip("Skipping table with no primary key columns")
	}
	if len(orcamentoVendaAllColumns) == len(orcamentoVendaPrimaryKeyColumns) {
		t.Skip("Skipping table with only primary key columns")
	}

	seed := randomize.NewSeed()
	var err error
	o := &OrcamentoVenda{}
	if err = randomize.Struct(seed, o, orcamentoVendaDBTypes, true, orcamentoVendaColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize OrcamentoVenda struct: %s", err)
	}

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()
	if err = o.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	}

	count, err := OrcamentoVendas().Count(ctx, tx)
	if err != nil {
		t.Error(err)
	}

	if count != 1 {
		t.Error("want one record, got:", count)
	}

	if err = randomize.Struct(seed, o, orcamentoVendaDBTypes, true, orcamentoVendaPrimaryKeyColumns...); err != nil {
		t.Errorf("Unable to randomize OrcamentoVenda struct: %s", err)
	}

	if rowsAff, err := o.Update(ctx, tx, boil.Infer()); err != nil {
		t.Error(err)
	} else if rowsAff != 1 {
		t.Error("should only affect one row but affected", rowsAff)
	}
}

